        long long res = 0;
        for (long long dx = 0; dx <= l; ++dx) {
            long long X = x + dx;
            long long rem = l - dx;

            long long minY = y;
            long long maxY = y + rem;
            long long minZ = z;
            long long maxZ = z + rem;

