using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long a, b, c, l;
    if (!(cin >> a >> b >> c >> l)) return 0;

    long long ans = 0;
    // Count all non-negative integer triples (x,y,z) with x+y+z<=l
    // This is sum_{t=0..l} C(t+2,2) = C(l+3,3)
    long long L = l;
    long long total = (L + 3) * (L + 2) * (L + 1) / 6;

    // Subtract configurations where triangle inequality fails:
    // For each side being the largest: a', b', c' with increments x,y,z
    // a' >= b' + c'  => a + x >= b + y + c + z
    // similarly for b', c'

    auto bad_for = [&](long long A, long long B, long long C) -> long long {
        long long res = 0;
        for (long long x = 0; x <= l; ++x) {
            long long T = l - x;
            long long D = A + x - B - C;
            if (D < 1) continue;
            long long y_min = 0;
            long long y_max = T;
            long long y_upper = T - D;
            if (y_upper < y_min) continue;
            y_max = min(y_max, y_upper);
            long long cnt_y = y_max - y_min + 1;
            if (cnt_y > 0) res += cnt_y;
        }
        return res;
    };

    long long bad = 0;
    bad += bad_for(a, b, c);
    bad += bad_for(b, a, c);
    bad += bad_for(c, a, b);

    ans = total - bad;
    cout << ans << '\n';
    return 0;
}

