    long long a, b, c, l;
    if (!(cin >> a >> b >> c >> l)) return 0;

    long long ans = 0;
    for (long long s = 0; s <= l; ++s) {
        long long total = 0;
        long long max_x = min(s, l); // x from 0..s

        // Case 1: (a + x) is max side
        {
            long long A = a, B = b, C = c;
            long long base = B + C - A;
            long long x_min = max(0LL, s - (B + C + l)); // always 0 effectively
            long long x_max = max_x;
            if (base <= 0) {
                // Need x > -base
                long long need = -base + 1;
                x_min = max(x_min, need);
            }
            if (x_min <= x_max) {
                long long cnt = x_max - x_min + 1;
                total += cnt;
            }
        }

        // Case 2: (b + y) is max side
        {
            long long A = b, B = a, C = c;
            long long base = B + C - A;
            long long y_min = 0;
            long long y_max = s;
            if (base <= 0) {
                long long need = -base + 1;
                y_min = max(y_min, need);
            }
            if (y_min <= y_max) {
                long long cnt = y_max - y_min + 1;
                total += cnt;
            }
        }

        // Case 3: (c + z) is max side
        {
            long long A = c, B = a, C = b;
            long long base = B + C - A;
            long long z_min = 0;
            long long z_max = s;
            if (base <= 0) {
                long long need = -base + 1;
                z_min = max(z_min, need);
            }
            if (z_min <= z_max) {
                long long cnt = z_max - z_min + 1;
                total += cnt;
            }
        }

        // Each triple (x,y,z) counted exactly once among the three cases
        ans += total;
    }

    cout << ans << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long a, b, c, l;
    if (!(cin >> a >> b >> c >> l)) return 0;

    long long ans = 0;
    // Total number of nonnegative integer triples (x,y,z) with x+y+z <= l
    // = sum_{s=0..l} C(s+2,2) = C(l+3,3)
    long long L = l;
    auto C3 = [&](long long n) -> long long {
        if (n < 3) return 0;
        return n * (n - 1) * (n - 2) / 6;
    };
    ans = C3(L + 3);

    long long sides[3] = {a, b, c};
    sort(sides, sides + 3);
    a = sides[0]; b = sides[1]; c = sides[2];

    // Subtract configurations where triangle inequality fails:
    // largest >= sum of other two
    // We iterate over which side is largest after increments.
    // Use inclusion-exclusion style known solution.

    // Function to subtract bad configurations for given base sides
    auto subtract_bad = [&](long long A, long long B, long long C) {
        // Assume C is the largest side initially (after sorting).
        // We consider increments x,y,z for A,B,C respectively.
        // Condition for bad: C+z >= A+x + B+y  =>  z - x - y >= A + B - C
        long long need = A + B - C;
        if (need <= 0) {
            // There exist bad configurations.
            // We iterate z from 0..l and count (x,y) with x+y <= l-z and z - x - y >= need.
            // That is x+y <= min(l-z, z-need).
            for (long long z = 0; z <= L; ++z) {
                long long maxSum = min(L - z, z - need);
                if (maxSum < 0) continue;
                // number of (x,y) with x,y>=0 and x+y<=maxSum is (maxSum+2 choose 2)
                ans -= (maxSum + 2) * (maxSum + 1) / 2;
            }
        }
    };

    // For each permutation where one side is considered largest
    subtract_bad(a, b, c);
    subtract_bad(a, c, b);
    subtract_bad(b, c, a);

    cout << ans << '\n';
    return 0;
}

