    long long ans = 0;
    for (long long s = 0; s <= l; ++s) {
        long long ways = s + 1; // number of (x,y,z) with x+y+z=s, x,y,z>=0

        // Case 1: a' >= b' + c'
        {
            long long T = b + c + s - a + 1;
            if (T > 0) {
                long long x_min = max(0LL, T);
                if (x_min <= s) {
                    long long bad = s - x_min + 1;
                    ways -= bad;
                }
            }
        }
        // Case 2: b' >= a' + c'
        {
            long long T = a + c + s - b + 1;
            if (T > 0) {
                long long y_min = max(0LL, T);
                if (y_min <= s) {
                    long long bad = s - y_min + 1;
                    ways -= bad;
                }
            }
        }
        // Case 3: c' >= a' + b'
        {
            long long T = a + b + s - c + 1;
            if (T > 0) {
                long long z_min = max(0LL, T);
                if (z_min <= s) {
                    long long bad = s - z_min + 1;
                    ways -= bad;
                }
            }
        }

        ans += ways;
    }

    cout << ans << '\n';
    return 0;
}

