        long long Cmin = c;
        long long Cmax = c + rem;

        long long total_pairs = (rem + 1) * (rem + 2) / 2;

        long long bad = 0;

        long long T = A + Bmin + Cmin;
        long long U = A + Bmax + Cmax;

