                        long long n = y2 - y1 + 1;
                        long long first = (Bmax + Cmax) - y1 + 1;
                        long long last = (Bmax + Cmax) - y2 + 1;
                        good += (first + last) * n / 2;
                    }

                    long long midL = max(x2 + 1, Bmin + Cmin + 1);
                    long long midR = min(y1 - 1, Bmax + Cmax - 1);
                    if (midL <= midR) {
                        long long n = midR - midL + 1;
