                        long long last = min(Bmax, midR - Cmin) - max(Bmin, midR - Cmax) + 1;
                        if (first > 0 && last > 0) {
                            good += (first + last) * n / 2;
                        }
                    }

                    bad = total_pairs - good;
                } else {
                    bad = total_pairs;
                }
            } else {
                bad = total_pairs;
