    cin.tie(nullptr);
    long long a, b, c, l;
    if (!(cin >> a >> b >> c >> l)) return 0;
    long long ans = 0;
    long long A[3] = {a, b, c};
    for (int i = 0; i < 3; ++i) {
        long long x = A[i];
        long long y = A[(i + 1) % 3];
        long long z = A[(i + 2) % 3];
        for (long long dx = 0; dx <= l; ++dx) {
            long long s = l - dx;
            long long total = s + 1;
            long long min_dy = max(0LL, z - y - x - dx + 1);
            if (min_dy > s) continue;
            long long bad = s - min_dy + 1;
            ans += total - bad;
        }
    }
    cout << ans << '\n';
    return 0;
}
